&lt;td&gt;&lt;a href="//./packages/svelte/README.md"&gt;Svelte README&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Solid&lt;/td&gt;
&lt;td&gt;&lt;a href="//./packages/solid"&gt;&lt;code&gt;@flow-render/solid&lt;/code&gt;&lt;/a&gt;&lt;/td&gt;
